<?php declare(strict_types=1);require_once __DIR__.'/includes/bootstrap.php';if(admin_id()){require __DIR__.'/admin_generic_redirect.php';exit;}require_user();$title='Investment Plans';$plans=dball('SELECT * FROM plans WHERE status=1 ORDER BY id DESC');require __DIR__.'/includes/header.php';?><div class="section-head"><div><h1>Investment Plans</h1><div class="muted">Choose a plan and fund your investment from your wallet.</div></div></div><div class="grid-2"><?php foreach($plans as $p):?><div class="card"><h2><?=e($p['name'])?></h2><p class="muted">Minimum: <?=e($p['price'])?> · Duration: <?=e($p['duration'])?> days</p><div class="stat"><?=e($p['percent']??$p['profit']??0)?>%</div><p>Expected plan return rate configured by the administrator.</p><a class="btn" href="invest.php?id=<?=$p['id']?>">Invest</a></div><?php endforeach;?></div><?php if(!$plans):?><div class="card">No active plans have been configured.</div><?php endif;?><?php require __DIR__.'/includes/footer.php';?>